  The first factor can be rewritten as
  \begin{align*}
    &\E_{u,v} \sum_h \bra{\psi}
      \Bigl((A^v_{h(v)} - A^u_{h(u)}) \cdot
      \sum_{o:(o,h)\in S_u} M^u_o \cdot
      (A^v_{h(v)} - A^u_{h(u)})\Bigr) \ot T_h \ket{\psi} \\
    &\le \E_{u,v} \sum_h \bra{\psi}
      (A^v_{h(v)} - A^u_{h(u)})^2 \ot T_h \ket{\psi},
  \end{align*}
  because $M^u$ is a submeasurement. Lemma~\ref{lem:global-variance-of-points}
  bounds this by~$\zeta_{\mathrm{variance}}$ since $T \in \polysub{m}{q}{d}$. The
  second factor is exactly the first factor
  from~\eqref{eq:move-second-point-projector-cauchy-schwarz},
  so it is at most~$1$.

The first factor can be rewritten as
  \begin{align*}
    &\E_{u,v} \sum_h \bra{\psi}
      \Bigl((A^v_{h(v)} - A^u_{h(u)}) \cdot
      \sum_{o:(o,h)\in S_u} M^u_o \cdot
      (A^v_{h(v)} - A^u_{h(u)})\Bigr) \ot T_h \ket{\psi} \\
    &\le \E_{u,v} \sum_h \bra{\psi}
      (A^v_{h(v)} - A^u_{h(u)})^2 \ot T_h \ket{\psi},
  \end{align*}
  because $M^u$ is a submeasurement.

\emph{Proof of \ref{item:self-improvement-projective-completeness}.}



  Lemma~\ref{prop:completeness-transfer-self-consistent-A} implies
  \[
    \bra{\psi} H \ot I \ket{\psi}
    \geq \bra{\psi} \widehat{H} \ot I \ket{\psi} - \widehat{\zeta} - 2\sqrt{\widehat{\zeta}_{\mathrm{ortho}}}
    \geq (1-\nu) - 2\widehat{\zeta} - 2\sqrt{\widehat{\zeta}_{\mathrm{ortho}}},
  \]
  where the second inequality is \ref{item:self-improvement-completeness} of Lemma~\ref{lem:self-improvement-helper}.

By \ref{prop:simeq-to-approx},
	\begin{equation} A_a^u \otimes I \approx_{2\gamma m} I \otimes L^\ell_{[f(u)=a]}.
	\end{equation}

Let $u$ and $v$ be independent uniformly random points in $\F_q^m$, and let $\ell$ be a uniformly random line containing both points. The marginal distribution on $(u,\ell)$ and on $(v,\ell)$ is the same as above, so
	\begin{align*}
		(A_a^u A_b^v) \ot I
		 & \approx_{2\gamma m} A_a^u \otimes L^\ell_{[f(v)=b]} \tag{by \ref{eq:point-diagonal-line-approx}}                           \\
		 & \approx_{2\gamma m} I \otimes \bigl(L^\ell_{[f(v)=b]} L^\ell_{[f(u)=a]}\bigr) \tag{by \ref{eq:point-diagonal-line-approx}} \\
		 & = I \otimes \bigl(L^\ell_{[f(u)=a]} L^\ell_{[f(v)=b]}\bigr) \tag{because~$L$ is projective}                                \\
		 & \approx_{2\gamma m} A_b^v \otimes L^\ell_{[f(u)=a]} \tag{by \ref{eq:point-diagonal-line-approx}}                           \\
		 & \approx_{2\gamma m} (A_b^v A_a^u) \ot I. \tag{by \ref{eq:point-diagonal-line-approx}}
	\end{align*}

Write $G_a^{u,x}=G^x_{[g(u)=a]}$. Expanding the commutator square gives
	\begin{align}
		 & \E_{u,v,x,y} \sum_{a,b} \bra{\psi}
		\bigl(G_a^{u,x} G_b^{v,y} - G_b^{v,y} G_a^{u,x}\bigr)^\dagger
		\bigl(G_a^{u,x} G_b^{v,y} - G_b^{v,y} G_a^{u,x}\bigr)
		\ot I \ket{\psi}\nonumber             \\
		 & = 2 \E_{u,v,x,y} \sum_{a,b}
		\Bigl(\bra{\psi} G_b^{v,y} G_a^{u,x} G_b^{v,y} \ot I \ket{\psi}
		- \bra{\psi} G_a^{u,x} G_b^{v,y} G_a^{u,x} G_b^{v,y} \ot I \ket{\psi}\Bigr), \end{align}
	using the projectivity of~$G$.

By \ref{item:data-processed-consistency} and \ref{prop:cons-sub-meas},
	\begin{align}
		G_a^{u,x} \ot I
		 & \approx_{4\zeta} G^{u,x} \ot A_a^{u,x}\nonumber \\
		 & = G^x \ot A_a^{u,x}, \end{align}
	where the last equality is \ref{eq:sum-of-gux}.

Applying \ref{prop:closeness-of-ip} once to the second term in \ref{eq:gcom8} gives
	\begin{align}
		                        & \E_{u,v,x,y} \sum_{a,b}
		\bra{\psi} G_a^{u,x} G_b^{v,y} G_a^{u,x} G_b^{v,y} \ot I \ket{\psi}\nonumber \\
		\approx_{2\sqrt{\zeta}} &
		\E_{u,v,x,y} \sum_{a,b}
		\bra{\psi} G_a^{u,x} G_b^{v,y} G_a^{u,x} G^y \ot A_b^{v,y} \ket{\psi}. \end{align}

The first boundedness-driven stability step is
	\begin{equation}
		\eqref{eq:apply-add-an-a-once}
		\approx_{\sqrt{\zeta}}
		\E_{u,v,x,y} \sum_{a,b}
		\bra{\psi} G_a^{u,x} G_b^{v,y} G_a^{u,x} \ot A_b^{v,y} \ket{\psi}, \end{equation}
	which is \ref{clm:g-comm-stability}.

Applying \ref{eq:add-an-a} once more and then \ref{thm:commutativity-points}, we obtain
	\begin{align}
		\eqref{eq:gcom9}
		 & \approx_{2\sqrt{\zeta}}
		\E_{u,v,x,y} \sum_{a,b}
		\bra{\psi} G_a^{u,x} G_b^{v,y} G^x \ot A_a^{u,x} A_b^{v,y} \ket{\psi}\nonumber \\
		 & \approx_{6\sqrt{\gamma(m+1)}}
		\E_{u,v,x,y} \sum_{a,b}
		\bra{\psi} G_a^{u,x} G_b^{v,y} G^x \ot A_b^{v,y} A_a^{u,x} \ket{\psi}. \end{align}

The second boundedness-driven stability step is
	\begin{equation}
		\eqref{eq:commuting-answer-swapped}
		\approx_{\sqrt{\zeta}+6\sqrt{\gamma(m+1)}}
		\E_{u,v,x,y} \sum_{a,b}
		\bra{\psi} G_a^{u,x} G_b^{v,y} \ot A_a^{u,x} A_b^{v,y} \ket{\psi}, \end{equation}
	which is \ref{clm:g-comm-stability2}.

Using \ref{eq:add-an-a} twice more and \ref{prop:closeness-of-ip},
	\begin{align}
		\eqref{eq:gcom10}
		 & \approx_{2\sqrt{\zeta}}
		\E_{u,v,x,y} \sum_{a,b}
		\bra{\psi} G_a^{u,x} G_b^{v,y} \ot A_b^{v,y} \ket{\psi}\nonumber \\
		 & \approx_{2\sqrt{\zeta}}
		\E_{u,v,x,y} \sum_{a,b}
		\bra{\psi} G_a^{u,x} G_b^{v,y} G_b^{v,y} \ot I \ket{\psi}. \end{align}

Next, \ref{item:data-processed-self-consistency} and the projectivity of~$G$ imply via \ref{prop:two-notions-of-self-consistency} and \ref{prop:two-notions-of-self-consistency-after-evaluation} that
	\begin{equation} G_a^{u,x} \ot I \approx_\zeta I \ot G_a^{u,x}.
	\end{equation}

The difference between the two sides of the lemma is
	\begin{align}
		 & \E_{u,v,x,y} \sum_{a,b}
		\bra{\psi} G_a^{u,x} G_b^{v,y} G_a^{u,x} (I-G^y) \ot A_b^{v,y} \ket{\psi}\nonumber \\
		 & = \E_{v,y} \sum_g
		\bra{\psi} R_g^y (I-G^y) \ot A_{g(v)}^{v,y} \ket{\psi}. \end{align}

The difference between the two sides is
	\begin{align}
		                              & \E_{u,v,x,y} \sum_{a,b}
		\bra{\psi} G_a^{u,x} G_b^{v,y} (I-G^x) \ot A_a^{u,x} A_b^{v,y} \ket{\psi}\nonumber \\
		\approx_{6\sqrt{\gamma(m+1)}} &
		\E_{u,v,x,y} \sum_{a,b}
		\bra{\psi} G_a^{u,x} G_b^{v,y} (I-G^x) \ot A_b^{v,y} A_a^{u,x} \ket{\psi}, \end{align}
	where \ref{thm:commutativity-points} commutes the point measurements on the right register.

Expanding $G_a^{u,x}=\sum_{g:g(u)=a} G_g^x$, we rewrite
	\begin{align}
		\eqref{eq:just-got-commuted}
		 & = \E_{u,v,x,y} \sum_{g,b}
		\bra{\psi} G_g^x G_b^{v,y} (I-G^x) \ot A_b^{v,y} A_{g(u)}^{u,x} \ket{\psi}. \end{align}

Expanding the commutator square gives
	\begin{align}
		 & \E_{x,y} \sum_{g,h}
		\bra{\psi}
		\bigl(G_g^x G_h^y - G_h^y G_g^x\bigr)^\dagger
		\bigl(G_g^x G_h^y - G_h^y G_g^x\bigr)
		\ot I \ket{\psi}\nonumber  \\
		 & = 2 \E_{x,y} \sum_{g,h}
		\bra{\psi} G_g^x G_h^y G_g^x \ot I \ket{\psi}
		- 2 \E_{x,y} \sum_{g,h}
		\bra{\psi} G_g^x G_h^y G_g^x G_h^y \ot I \ket{\psi}. \end{align}

For the second term, \ref{prop:closeness-of-ip} and \ref{lem:normalization-condition} yield
	\begin{equation}
		\E_{x,y} \sum_{g,h}
		\bra{\psi} G_g^x G_h^y G_g^x G_h^y \ot I \ket{\psi}
		\approx_{\sqrt{\zeta}}
		\E_{x,y} \sum_{g,h}
		\bra{\psi} G_h^y G_g^x G_h^y \ot G_g^x \ket{\psi}. \end{equation}

The first Schwartz--Zippel reduction evaluates the left factor at a random point:
	\begin{align}
		\eqref{eq:gcom4}
		 & = \E_{x,y} \sum_{g,h}
		\bra{\psi} G_h^y G_g^x G_h^y \ot G_g^x \ket{\psi}\nonumber \\
		 & \approx_{\frac{dm}{q}}
		\E_{u,x,y} \sum_{a,h}
		\bra{\psi} G_h^y G^x_{[g(u)=a]} G_h^y \ot G^x_{[g(u)=a]} \ket{\psi}. \end{align}
	Indeed, the difference is
	\begin{equation} \E_{u,x,y} \sum_{g \neq g',h}
		\bone[g(u)=g'(u)]
		\bra{\psi} G_h^y G_g^x G_h^y \ot G_{g'}^x \ket{\psi},
	\end{equation}
	and \ref{lem:schwartz-zippel-individual} bounds this by $dm/q$.

Next, apply \ref{prop:closeness-of-ip} twice:
	\begin{align}
		\eqref{eq:evaluate-gcom-at-points}
		 & = \E_{u,x,y} \sum_{a,h}
		\bra{\psi} G_h^y G^x_{[g(u)=a]} G_h^y \ot G^x_{[g(u)=a]} \ket{\psi}\nonumber   \\
		 & \approx_{\sqrt{\zeta}}
		\E_{u,x,y} \sum_{a,h}
		\bra{\psi} G^x_{[g(u)=a]} G_h^y G^x_{[g(u)=a]} G_h^y \ot I \ket{\psi}\nonumber \\
		 & \approx_{\sqrt{\zeta}}
		\E_{u,x,y} \sum_{a,h}
		\bra{\psi} G^x_{[g(u)=a]} G_h^y G^x_{[g(u)=a]} \ot G_h^y \ket{\psi}. \end{align}

A second Schwartz--Zippel reduction evaluates the right factor at an independent point:
	\begin{align}
		\eqref{eq:don't-understand-the-numbering-system}
		 & = \E_{u,x,y} \sum_{a,h}
		\bra{\psi} G^x_{[g(u)=a]} G_h^y G^x_{[g(u)=a]} \ot G_h^y \ket{\psi}\nonumber \\
		 & \approx_{\frac{dm}{q}}
		\E_{u,v,x,y} \sum_{a,b}
		\bra{\psi}
		G^x_{[g(u)=a]} G^y_{[h(v)=b]} G^x_{[g(u)=a]}
		\ot G^y_{[h(v)=b]} \ket{\psi}. \end{align}
	The difference is
	\begin{equation} \E_{u,v,x,y} \sum_{a,h \neq h'}
		\bone[h(v)=h'(v)]
		\bra{\psi}
		G^x_{[g(u)=a]} G_h^y G^x_{[g(u)=a]} \ot G_{h'}^y \ket{\psi},
	\end{equation}
	and the same Schwartz--Zippel estimate again gives the loss $dm/q$.

Let $H$ be the submeasurement from Lemma~\ref{lem:ld-pasting-sub-measurement}, and fix an arbitrary polynomial $h^* \in \polyfunc{m+1}{q}{d}$. Define a measurement $H_{\mathrm{meas}} \in \polymeas{m+1}{q}{d}$ by
	\[
		(H_{\mathrm{meas}})_h
		=
		\begin{cases}
			H_{h^*} + (I-H) & \text{if } h=h^*, \\
			H_h             & \text{otherwise.}
		\end{cases}
	\]

Moreover,
	\begin{align*}
		      & \E_u \sum_{a \ne b} \bra{\psi} A_a^u \ot (H_{\mathrm{meas}})_{[h(u)=b]} \ket{\psi}                            \\
		={}   & \E_u \sum_a \sum_{h:h(u)\ne a} \bra{\psi} A_a^u \ot (H_{\mathrm{meas}})_h \ket{\psi}                          \\
		={}   & \E_u \sum_a \sum_{h:h(u)\ne a} \bra{\psi} A_a^u \ot H_h \ket{\psi}
		+ \E_u \sum_{a:h^*(u)\ne a} \bra{\psi} A_a^u \ot (I-H) \ket{\psi}                                                     \\
		\le{} & \E_u \sum_a \sum_{h:h(u)\ne a} \bra{\psi} A_a^u \ot H_h \ket{\psi}
		+ \E_u \bra{\psi} I \ot (I-H) \ket{\psi}                                                                              \\
		\le{} & \nu + \left(\kappa\left(1+\frac{1}{100m}\right) + \nu + e^{-k/(80000m^2)}\right)
		\tag{by \ref{item:ld-pasting-N-consistency-sub-measurement} and \ref{item:ld-pasting-N-completeness-sub-measurement}} \\
		={}   & \sigma.
	\end{align*}

Lemma~\ref{lem:h-b-consistency} implies
	\begin{equation} H_{[h(u,x)=a]} \ot I \simeq_{\nu_6} I \ot B^u_{[f(x)=a]}.
	\end{equation}

Let $M = \E_y \sum_o M_o^y$. The error to bound is
	\begin{align}
		    & \E_{x,y} \sum_o \|(G^xM_o^y - M_o^yG^x)\ot I \ket{\psi}\|^2 \nonumber \\
		={} & \E_{x,y} \sum_o \bra{\psi} M_o^y (G^x)^2 M_o^y \ot I \ket{\psi}
		+ \E_{x,y} \sum_o \bra{\psi} G^x (M_o^y)^2 G^x \ot I \ket{\psi} \nonumber   \\
		    & \qquad
		- \E_{x,y} \sum_o \bra{\psi} G^x M_o^y G^x M_o^y \ot I \ket{\psi}
		- \E_{x,y} \sum_o \bra{\psi} M_o^y G^x M_o^y G^x \ot I \ket{\psi}. \end{align}

For the first term in \ref{eq:g-commute-with-gg-error},
	\begin{align*}
		\E_{x,y} \sum_o \bra{\psi} M_o^y (G^x)^2 M_o^y \ot I \ket{\psi}
		 & =
		\E_{x,y} \sum_o \bra{\psi} M_o^y G^x M_o^y \ot I \ket{\psi}               \\
		 & =
		\E_y \sum_o \bra{\psi} M_o^y G M_o^y \ot I \ket{\psi}                     \\
		 & \approx_{2\sqrt{\omega}} \E_y \sum_o \bra{\psi} G \ot M_o^y \ket{\psi}
		\tag{by \ref{prop:switch-sandwich} and \ref{eq:M-self-consistent}}        \\
		 & =
		\bra{\psi} G \ot M \ket{\psi}.
	\end{align*}

For the second term,
	\begin{align*}
		\E_{x,y} \sum_o \bra{\psi} G^x (M_o^y)^2 G^x \ot I \ket{\psi}
		 & =
		\E_{x,y} \sum_o \bra{\psi} G^x M_o^y G^x \ot I \ket{\psi}                     \\
		 & =
		\E_x \bra{\psi} G^x M G^x \ot I \ket{\psi}                                    \\
		 & \approx_{2\sqrt{\zeta}} \E_x \bra{\psi} M \ot G^x \ket{\psi}
		\tag{by \ref{prop:switch-sandwich} and \ref{lem:g-complete-self-consistency}} \\
		 & =
		\bra{\psi} M \ot G \ket{\psi}.
	\end{align*}

For the third term, first
	\begin{align}
		\E_{x,y} \sum_o \bra{\psi} G^x M_o^y G^x M_o^y \ot I \ket{\psi}
		 & =
		\E_{x,y} \sum_{o,g} \bra{\psi} G^x M_o^y G_g^x G_g^x M_o^y \ot I \ket{\psi} \nonumber \\
		 & \approx_{\sqrt{\chi}}
		\E_{x,y} \sum_{o,g} \bra{\psi} G^x M_o^y G_g^x M_o^y G_g^x \ot I \ket{\psi}. \end{align}
	This is the Cauchy--Schwarz estimate coming from \ref{eq:M-commutes-with-G}. Next,
	\begin{equation} \eqref{eq:split-G-and-commute}
		\approx_{\sqrt{\zeta}}
		\E_{x,y} \sum_{o,g} \bra{\psi} G^x M_o^y G_g^x M_o^y \ot G_g^x \ket{\psi}.
	\end{equation}
	Here the error is bounded using \ref{item:ld-pasting-self-consistency}. Then
	\begin{equation} \eqref{eq:move-G-to-right-factor}
		\approx_{\sqrt{\zeta}}
		\E_{x,y} \sum_{o,g} \bra{\psi} G_g^x G^x M_o^y G_g^x M_o^y \ot I \ket{\psi},
	\end{equation}
	again by strong self-consistency of $G_g^x$. Since $G$ is projective,
	\begin{align}
		\eqref{eq:move-G-back-to-left-factor}
		 & =
		\E_{x,y} \sum_{o,g} \bra{\psi} G_g^x M_o^y G_g^x M_o^y \ot I \ket{\psi} \nonumber \\
		 & \approx_{\sqrt{\chi}}
		\E_{x,y} \sum_{o,g} \bra{\psi} M_o^y G_g^x G_g^x M_o^y \ot I \ket{\psi}. \end{align}
	Finally,
	\begin{align*}
		\eqref{eq:commuted-G-after-transfer}
		 & =
		\E_{x,y} \sum_{o,g} \bra{\psi} M_o^y G_g^x M_o^y \ot I \ket{\psi}         \\
		 & =
		\E_y \sum_o \bra{\psi} M_o^y G M_o^y \ot I \ket{\psi}                     \\
		 & \approx_{2\sqrt{\omega}} \E_y \sum_o \bra{\psi} G \ot M_o^y \ket{\psi}
		\tag{by \ref{prop:switch-sandwich} and \ref{eq:M-self-consistent}}        \\
		 & =
		\bra{\psi} G \ot M \ket{\psi}.
	\end{align*}
	Therefore
	\begin{equation} \E_{x,y} \sum_o \bra{\psi} G^x M_o^y G^x M_o^y \ot I \ket{\psi}
		\approx_{2\sqrt{\zeta}+2\sqrt{\omega}+2\sqrt{\chi}}
		\bra{\psi} G \ot M \ket{\psi}.
	\end{equation}

For the third term, first
	\begin{align}
		\E_{x,y} \sum_o \bra{\psi} G^x M_o^y G^x M_o^y \ot I \ket{\psi}
		 & =
		\E_{x,y} \sum_{o,g} \bra{\psi} G^x M_o^y G_g^x G_g^x M_o^y \ot I \ket{\psi} \nonumber \\
		 & \approx_{\sqrt{\chi}}
		\E_{x,y} \sum_{o,g} \bra{\psi} G^x M_o^y G_g^x M_o^y G_g^x \ot I \ket{\psi}. \end{align}
	This is the Cauchy--Schwarz estimate coming from \ref{eq:M-commutes-with-G}.

Next,
	\begin{equation} \eqref{eq:split-G-and-commute}
		\approx_{\sqrt{\zeta}}
		\E_{x,y} \sum_{o,g} \bra{\psi} G^x M_o^y G_g^x M_o^y \ot G_g^x \ket{\psi}.
	\end{equation}
	Here the error is bounded using \ref{item:ld-pasting-self-consistency}.

Then
	\begin{equation} \eqref{eq:move-G-to-right-factor}
		\approx_{\sqrt{\zeta}}
		\E_{x,y} \sum_{o,g} \bra{\psi} G_g^x G^x M_o^y G_g^x M_o^y \ot I \ket{\psi},
	\end{equation}
	again by strong self-consistency of $G_g^x$.

Since $G$ is projective,
	\begin{align}
		\eqref{eq:move-G-back-to-left-factor}
		 & =
		\E_{x,y} \sum_{o,g} \bra{\psi} G_g^x M_o^y G_g^x M_o^y \ot I \ket{\psi} \nonumber \\
		 & \approx_{\sqrt{\chi}}
		\E_{x,y} \sum_{o,g} \bra{\psi} M_o^y G_g^x G_g^x M_o^y \ot I \ket{\psi}. \end{align}

Finally,
	\begin{align*}
		\eqref{eq:commuted-G-after-transfer}
		 & =
		\E_{x,y} \sum_{o,g} \bra{\psi} M_o^y G_g^x M_o^y \ot I \ket{\psi}         \\
		 & =
		\E_y \sum_o \bra{\psi} M_o^y G M_o^y \ot I \ket{\psi}                     \\
		 & \approx_{2\sqrt{\omega}} \E_y \sum_o \bra{\psi} G \ot M_o^y \ket{\psi}
		\tag{by \ref{prop:switch-sandwich} and \ref{eq:M-self-consistent}}        \\
		 & =
		\bra{\psi} G \ot M \ket{\psi}.
	\end{align*}

Therefore
	\begin{equation} \E_{x,y} \sum_o \bra{\psi} G^x M_o^y G^x M_o^y \ot I \ket{\psi}
		\approx_{2\sqrt{\zeta}+2\sqrt{\omega}+2\sqrt{\chi}}
		\bra{\psi} G \ot M \ket{\psi}.
	\end{equation}

By \ref{eq:complete-slice-commutativity},
	\begin{equation} G_g^x G_h^y \ot I \approx_{\nu_{\mathrm{com}}} G_h^y G_g^x \ot I.
	\end{equation}

Summing out the coordinates to the right of $i$ gives
	\begin{equation} \begin{aligned}
			    & \E_u \E_{x_1,\dots,x_k} \sum_{g_1,\dots,g_k\,:\,g_i\ne\bot} \sum_{a\ne g_i(u)}
			\bra{\psi} \widehat H_{g_1,\dots,g_k}^{x_1,\dots,x_k} \ot B_{[f(x_i)=a]}^u \ket{\psi} \\
			={} &
			\E_u \E_{x_1,\dots,x_i} \sum_{g_1,\dots,g_i\,:\,g_i\ne\bot} \sum_{a\ne g_i(u)}
			\bra{\psi} \widehat H_{g_1,\dots,g_i}^{x_1,\dots,x_i} \ot B_{[f(x_i)=a]}^u \ket{\psi}.
		\end{aligned}
	\end{equation}

Write $\widehat G_{g_{<i}}^{x_{<i}} = \widehat G_{g_1}^{x_1}\cdots \widehat G_{g_{i-1}}^{x_{i-1}}$. Then
