		\E_{x_{\ge \ell}} \sum_{\tau_{\ge \ell}} \sum_{(g_\ell,g_{>\ell})\in \mathsf O_{\tau_{\ge \ell}}}
		\bra{\psi}
		\widehat H_{g_{>\ell}}^{x_{>\ell}}
		\ot \bigl(S_{\tau_{\ge \ell}}\widehat G_{g_\ell}^{x_\ell}\bigr)
		\ket{\psi} \\
		 & =
		\E_{x_{>\ell}} \sum_{\tau_{>\ell}} \sum_{g_{>\ell}\in \mathsf O_{\tau_{>\ell}}}
		\bra{\psi}
		\widehat H_{g_{>\ell}}^{x_{>\ell}}
		\ot
		\Bigl(\sum_{\tau_\ell}
		S_{\tau_{\ge \ell}}
		\Bigl(\E_{x_\ell}\sum_{g_\ell\in \mathsf O_{\tau_\ell}} \widehat G_{g_\ell}^{x_\ell}\Bigr)\Bigr)
		\ket{\psi} \\
		 & =
		\E_{x_{>\ell}} \sum_{\tau_{>\ell}} \sum_{g_{>\ell}\in \mathsf O_{\tau_{>\ell}}}
		\bra{\psi}
		\widehat H_{g_{>\ell}}^{x_{>\ell}} \ot S_{\tau_{>\ell}}
		\ket{\psi}
		\tag{by \ref{eq:S-recurrence}},
	\end{align*}
	which is exactly \ref{eq:bernoulli-tail-stage-reduction-expanded}.

Lemma~\ref{lem:over-all-outcomes} gives
	\[
		\bra{\psi} H \ot I \ket{\psi}
		\approx_{\nu_7}
		\E_{x_1,\dots,x_k} \sum_{\tau:\,|\tau|\ge d+1} \sum_{(g_1,\dots,g_k)\in \mathsf{Outcomes}_\tau}
		\bra{\psi} \widehat H_{g_1,\dots,g_k}^{x_1,\dots,x_k} \ot I \ket{\psi}.
	\]

\[
			      \widehat G_g^x \ot I \approx_{\zeta_x} I \ot \widehat G_g^x;
		      \]

Since $A_{\mathrm{sym}}$ is a convex combination of $(\ket{0}\bra{0} \ot I)$ and $(\ket{1}\bra{1} \ot I)$ weighted by the test probabilities, the cross-terms $\bra{0} \cdot A_{\mathrm{sym}} \cdot \ket{1}$ vanish. Expanding the consistency of $G$ gives
	\begin{gather}
		G_{[g(u)=a]}^{\mathrm A} \ot I \simeq_{2\sigma} I \ot A_a^{\mathrm B,u}, \\
		I \ot G_{[g(u)=a]}^{\mathrm B} \simeq_{2\sigma} A_a^{\mathrm A,u} \ot I. \end{gather}

Because both measurements are projective, Lemma~\ref{prop:simeq-to-approx} converts this to
	\begin{equation} Q_g^{\mathrm A} \ot I \simeq_{\zeta_3/2} I \ot Q_g^{\mathrm B}.
	\end{equation}
	By data processing,
	\begin{equation} Q_{[g(u)=a]}^{\mathrm A} \ot I \simeq_{\zeta_3/2} I \ot Q_{[g(u)=a]}^{\mathrm B}.
	\end{equation}

The same argument with the roles reversed gives
	\begin{equation} I \ot A_a^{\mathrm B,u} \simeq_{\zeta_4} Q_{[g(u)=a]}^{\mathrm A} \ot I.
	\end{equation}
